<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Conway's Game of Life</title>
<style>
  :root {
    color-scheme: dark;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    background: radial-gradient(circle at 50% 20%, #1a1f2b 0%, #0b0d13 70%);
    color: #e8e8f0;
    font-family: 'Segoe UI', system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 18px;
    padding: 24px;
  }
  h1 {
    margin: 0;
    font-size: 1.6rem;
    letter-spacing: 0.05em;
    background: linear-gradient(90deg, #6ee7ff, #b28dff, #ff8dc7);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
  #wrap {
    background: #12141c;
    border: 2px solid #2b2f3d;
    border-radius: 16px;
    padding: 14px;
    box-shadow: 0 0 40px rgba(110, 231, 255, 0.08), inset 0 0 20px rgba(0,0,0,0.5);
  }
  #life {
    display: block;
    background: #05060a;
    border-radius: 8px;
    cursor: crosshair;
    touch-action: none;
  }
  #controls {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    background: #1d2130;
    color: #e8e8f0;
    border: 1px solid #383f55;
    border-radius: 10px;
    padding: 10px 18px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: transform 0.08s ease, background 0.15s ease, box-shadow 0.15s ease;
  }
  button:hover {
    background: #272c40;
    box-shadow: 0 0 12px rgba(110, 231, 255, 0.25);
  }
  button:active {
    transform: scale(0.95);
  }
  #play.active {
    background: linear-gradient(90deg, #2c5f4f, #1f7a5c);
    border-color: #2fbf8f;
    box-shadow: 0 0 14px rgba(47, 191, 143, 0.4);
  }
  .info {
    font-size: 0.8rem;
    color: #7a8099;
  }
</style>
</head>
<body>

<h1>Conway's Game of Life</h1>

<div id="wrap">
  <canvas id="life" width="420" height="420"></canvas>
</div>

<div id="controls">
  <button id="step">⏭ Step</button>
  <button id="play">▶ Play</button>
  <button id="random">🎲 Random</button>
  <button id="clear">🧹 Clear</button>
</div>

<div class="info">Click or drag on the grid to paint cells alive.</div>

<script>
(function () {
  const W = 50, H = 50; // grid dimensions (>= 40x40)
  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');

  const cssSize = 420; // >= 400 CSS px
  canvas.style.width = cssSize + 'px';
  canvas.style.height = cssSize + 'px';

  // Handle device pixel ratio for crisp rendering while keeping CSS size fixed.
  const dpr = window.devicePixelRatio || 1;
  canvas.width = cssSize * dpr;
  canvas.height = cssSize * dpr;
  ctx.scale(dpr, dpr);

  const cellSize = cssSize / W; // note: H may differ; we'll compute cellH separately
  const cellW = cssSize / W;
  const cellH = cssSize / H;

  let grid = new Uint8Array(W * H);

  function idx(x, y) { return y * W + x; }

  function get(x, y) {
    if (x < 0 || y < 0 || x >= W || y >= H) return 0;
    return grid[idx(x, y)];
  }

  function set(x, y, v) {
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    grid[idx(x, y)] = v ? 1 : 0;
    draw();
  }

  function clear() {
    grid.fill(0);
    draw();
  }

  function countNeighbors(x, y) {
    let count = 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        count += get(x + dx, y + dy);
      }
    }
    return count;
  }

  function step() {
    const next = new Uint8Array(W * H);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const alive = grid[idx(x, y)];
        const n = countNeighbors(x, y);
        let nextAlive = 0;
        if (alive) {
          nextAlive = (n === 2 || n === 3) ? 1 : 0;
        } else {
          nextAlive = (n === 3) ? 1 : 0;
        }
        next[idx(x, y)] = nextAlive;
      }
    }
    grid = next;
    draw();
  }

  function randomize() {
    for (let i = 0; i < grid.length; i++) {
      grid[i] = (window.crypto && window.crypto.getRandomValues)
        ? (cryptoRandomBit())
        : (Math.random() < 0.25 ? 1 : 0);
    }
    draw();
  }

  // simple crypto-based random bit generator (fallback used above via Math.random too)
  let randBuf = null, randBufIdx = 0;
  function cryptoRandomBit() {
    if (!randBuf || randBufIdx >= randBuf.length) {
      randBuf = new Uint8Array(1024);
      window.crypto.getRandomValues(randBuf);
      randBufIdx = 0;
    }
    const byte = randBuf[randBufIdx++];
    return (byte / 255) < 0.25 ? 1 : 0;
  }

  function draw() {
    ctx.clearRect(0, 0, cssSize, cssSize);

    // subtle grid lines
    ctx.strokeStyle = 'rgba(255,255,255,0.04)';
    ctx.lineWidth = 1;
    for (let x = 0; x <= W; x++) {
      ctx.beginPath();
      ctx.moveTo(x * cellW, 0);
      ctx.lineTo(x * cellW, cssSize);
      ctx.stroke();
    }
    for (let y = 0; y <= H; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * cellH);
      ctx.lineTo(cssSize, y * cellH);
      ctx.stroke();
    }

    // live cells
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (grid[idx(x, y)]) {
          const gradient = ctx.createLinearGradient(
            x * cellW, y * cellH, (x + 1) * cellW, (y + 1) * cellH
          );
          gradient.addColorStop(0, '#6ee7ff');
          gradient.addColorStop(1, '#b28dff');
          ctx.fillStyle = gradient;
          ctx.shadowColor = 'rgba(110, 231, 255, 0.6)';
          ctx.shadowBlur = 4;
          ctx.fillRect(
            x * cellW + 1, y * cellH + 1,
            cellW - 2, cellH - 2
          );
          ctx.shadowBlur = 0;
        }
      }
    }
  }

  // --- Painting interaction ---
  let painting = false;
  let paintValue = 1;

  function cellFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const px = (e.clientX - rect.left) / rect.width * cssSize;
    const py = (e.clientY - rect.top) / rect.height * cssSize;
    const x = Math.floor(px / cellW);
    const y = Math.floor(py / cellH);
    return { x, y };
  }

  canvas.addEventListener('pointerdown', (e) => {
    painting = true;
    const { x, y } = cellFromEvent(e);
    paintValue = get(x, y) ? 0 : 1;
    set(x, y, paintValue);
  });

  canvas.addEventListener('pointermove', (e) => {
    if (!painting) return;
    const { x, y } = cellFromEvent(e);
    set(x, y, paintValue);
  });

  window.addEventListener('pointerup', () => { painting = false; });
  canvas.addEventListener('pointerleave', () => {});

  // --- Buttons ---
  const stepBtn = document.getElementById('step');
  const playBtn = document.getElementById('play');
  const randomBtn = document.getElementById('random');
  const clearBtn = document.getElementById('clear');

  let playing = false;
  let timer = null;

  function startPlaying() {
    playing = true;
    playBtn.textContent = '⏸ Pause';
    playBtn.classList.add('active');
    timer = setInterval(step, 120);
  }

  function stopPlaying() {
    playing = false;
    playBtn.textContent = '▶ Play';
    playBtn.classList.remove('active');
    if (timer) clearInterval(timer);
    timer = null;
  }

  stepBtn.addEventListener('click', () => { step(); });
  playBtn.addEventListener('click', () => {
    if (playing) stopPlaying(); else startPlaying();
  });
  randomBtn.addEventListener('click', () => { randomize(); });
  clearBtn.addEventListener('click', () => { stopPlaying(); clear(); });

  draw();

  // --- Programmatic API ---
  window.life = {
    w: W,
    h: H,
    get,
    set,
    step,
    clear,
  };
})();
</script>

</body>
</html>
